const express = require('express');
const crypto = require('crypto');
const { UserTenantMapping, OrganizationInvitation } = require('../models/tenantMapping');

const app = express();
app.use(express.json());

app.post('/api/webhooks/auth0/post-login', async (req, res) => {
  // Verify Auth0 webhook signature header using pre-shared HMAC key
  const signature = req.headers['x-auth0-signature'];
  const expectedSig = crypto
    .createHmac('sha256', process.env.AUTH0_WEBHOOK_SECRET)
    .update(JSON.stringify(req.body))
    .digest('hex');

  if (!signature || signature !== expectedSig) {
    return res.status(401).json({ error: 'Invalid webhook signature' });
  }

  const { user_id, target_organization_id, connection } = req.body;

  if (!user_id || !target_organization_id) {
    return res.status(400).json({ error: 'Missing webhook attributes' });
  }

  // Verify that the user has an active membership or invitation in the target organization
  const hasMembership = await OrganizationInvitation.verifyUserInOrg(user_id, target_organization_id);
  if (!hasMembership) {
    return res.status(403).json({ error: 'Access denied: user is not a provisioned member of target organization' });
  }

  const mapping = await UserTenantMapping.findOneAndUpdate(
    { auth0UserId: user_id },
    {
      activeTenantId: target_organization_id,
      identityProvider: connection,
      lastSwitchedAt: new Date()
    },
    { upsert: true, new: true }
  );

  res.json({ status: 'TENANT_UPDATED', mapping });
});

app.listen(9001);
